Get a Home Insurance Policy > API /home-insurance-policies/{InsurancePolicyId}

{
  "info": {
    "title": "UAE Insurance API",
    "description": "## UAE Open Finance Insurance API Specification",
    "version": "v2.1-errata3"
  },
  "servers": [
    {
      "url": "https://rs1.[LFICODE].apihub.openfinance.ae/open-finance/insurance/v2.1"
    },
    {
      "url": "https://rs1.[LFICODE].preprod.apihub.openfinance.ae/open-finance/insurance/v2.1"
    },
    {
      "url": "https://rs1.altareq1.sandbox.apihub.openfinance.ae/open-finance/insurance/v2.1"
    }
  ],
  "source_path": "/home-insurance-policies/{InsurancePolicyId}",
  "operations": {
    "get": {
      "operationId": "HomeInsurancePoliciesById_read",
      "summary": "Retrieve a home insurance policy",
      "description": "Retrieve an insurance policy for a given insurance policy identifier value, based \non data clusters granted by the User.",
      "parameters": [
        {
          "$ref": "#/components/parameters/Authorization"
        },
        {
          "$ref": "#/components/parameters/x-customer-user-agent"
        },
        {
          "$ref": "#/components/parameters/x-fapi-auth-date"
        },
        {
          "$ref": "#/components/parameters/x-fapi-customer-ip-address"
        },
        {
          "$ref": "#/components/parameters/x-fapi-interaction-id"
        },
        {
          "$ref": "#/components/parameters/AEInsuranceParameters.AEInsurancePolicyId"
        }
      ],
      "responses": {
        "200": {
          "description": "The request has succeeded.",
          "headers": {
            "x-fapi-interaction-id": {
              "required": false,
              "description": "An RFC4122 UID used as a correlation ID.",
              "schema": {
                "type": "string"
              }
            }
          },
          "content": {
            "application/json; charset=utf-8": {
              "schema": {
                "$ref": "#/components/schemas/AEReadHomeInsurancePolicy1"
              }
            },
            "application/json": {
              "schema": {
                "$ref": "#/components/schemas/AEReadHomeInsurancePolicy1"
              }
            },
            "application/jwt": {
              "schema": {
                "$ref": "#/components/schemas/AEReadHomeInsurancePolicy1Signed"
              }
            }
          }
        },
        "400": {
          "$ref": "#/components/responses/400Error"
        },
        "401": {
          "$ref": "#/components/responses/401Error"
        },
        "403": {
          "$ref": "#/components/responses/403Error"
        },
        "404": {
          "$ref": "#/components/responses/404Error"
        },
        "405": {
          "$ref": "#/components/responses/405Error"
        },
        "406": {
          "$ref": "#/components/responses/406Error"
        },
        "415": {
          "$ref": "#/components/responses/415Error"
        },
        "429": {
          "$ref": "#/components/responses/429Error"
        },
        "500": {
          "$ref": "#/components/responses/500Error"
        }
      },
      "tags": [
        "Home Insurance"
      ],
      "security": [
        {
          "UserOAuth2Security": [
            "openid",
            "insurance"
          ]
        }
      ]
    }
  }
}

